Lemma vstr_at_keep o s : 0 <= o -> o + 24 <= 2 ^ 64 -> ag o 24 -> (forall c n p, s = PM.VLong c n p -> dkr M M' p c) ->
  PM.vstr_at segs T3 M o s -> PM.vstr_at segs T3 M' o s.
