Lemma iss_upd ois str sm g' st' :
  PM.iss_at segs A T3 M ois str sm -> 0 <= ois -> ois + 272 <= 2 ^ 64 ->
  ag ois 40 -> ag (ois + 48) 104 -> ag (ois + 156) 116 -> dkr M M' (ois + 40) 8 -> dkr M M' (ois + 152) 4 ->
