Lemma vec_at_pop v b k stk :
  PM.vec_at segs T3 T4 M v b k stk -> (1 <= length stk)%nat -> 0 <= v -> v + 24 <= 2 ^ 64 -> 0 <= b -> b + 32 * 2 ^ k <= 2 ^ 64 ->
  ag v 8 -> ag (v + 16) 8 -> ag b (32 * 2 ^ k) ->
  L5.u64_at segs M' (v + 8) (b + 32 * Z.of_nat (length stk) - 32) ->
